<?php
session_start();
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../config/helpers.php';
require_permission('gate', 'view');
ensure_gate_schema();
$id = (int) ($_GET['id'] ?? 0);
$stmt = $pdo->prepare("SELECT gc.*, s.invoice_no, s.total_amount, s.paid_amount, s.balance, s.payment_method, s.payment_reference, s.created_at AS sale_created_at, c.name AS customer_name, c.phone AS customer_phone FROM gate_clearances gc JOIN sales s ON s.id=gc.sale_id LEFT JOIN customers c ON c.id=gc.customer_id WHERE gc.id=?");
$stmt->execute([$id]);
$clearance = $stmt->fetch();
if (!$clearance) {
    render_not_found(t('clearance_not_found'), t('clearance_not_found_hint'), '/block_plant/gate/index.php', t('gate'));
}
if (empty($clearance['printed_at'])) {
    $pdo->prepare("UPDATE gate_clearances SET printed_at = NOW() WHERE id = ? AND printed_at IS NULL")->execute([$id]);
}
$itemStmt = $pdo->prepare("SELECT si.quantity, si.unit_price, bt.name, bt.size FROM sale_items si JOIN block_types bt ON bt.id=si.block_type_id WHERE si.sale_id=?");
$itemStmt->execute([$clearance['sale_id']]);
$items = $itemStmt->fetchAll();
$company = company_settings();
$verifyUrl = '/block_plant/gate/index.php?token=' . urlencode($clearance['qr_token']);
$pageTitle = 'Gate Clearance ' . $clearance['clearance_number'];
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?></title><style>body{font-family:Arial,sans-serif;background:#eef3f1;color:#19323c;margin:0}.sheet{max-width:800px;margin:24px auto;background:#fff;padding:34px;box-shadow:0 8px 24px #1f293320}.head{display:flex;justify-content:space-between;border-bottom:3px solid #b8481b;padding-bottom:18px}.head h1{margin:0;color:#1f2933;font-size:23px}.meta{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:20px 0}.meta div{padding:10px;background:#f1f8f5;border-radius:6px}.meta strong{display:block;font-size:11px;color:#6a6259;text-transform:uppercase}.items{width:100%;border-collapse:collapse;margin:18px 0}.items th{background:#19323c;color:#fff;text-align:left}.items th,.items td{padding:10px;border-bottom:1px solid #e3ddd4}.total{margin-left:auto;width:280px}.total div{display:flex;justify-content:space-between;padding:6px}.status{padding:12px;text-align:center;background:#dcfce7;color:#166534;font-weight:bold;border-radius:6px;margin:18px 0}.sign{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin-top:50px}.sign div{border-top:1px solid #6a6259;padding-top:8px;font-size:12px}.qr{text-align:center;margin-top:24px}.qr img{width:140px;height:140px}.print{margin:12px auto;display:block;padding:10px 18px;background:#e8a33d;color:#fff;border:0;border-radius:6px}@media print{@page{margin:12mm}*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}body{background:#fff}.sheet{margin:0;max-width:none;box-shadow:none;padding:0}.print{display:none!important}.meta,.items,.total,.status,.sign,tr{page-break-inside:avoid;break-inside:avoid}.items thead{display:table-header-group}}@media(max-width:600px){.sheet{padding:18px}.head,.meta{grid-template-columns:1fr;display:grid}.sign{grid-template-columns:1fr}}</style></head><body><main class="sheet"><button class="print" onclick="window.print()">Print gate clearance</button><header class="head"><div><h1><?= e($company['company_name'] ?? 'Block Manufacturing Company') ?></h1><div>SALES &amp; GATE CLEARANCE</div></div><div><strong><?= e($clearance['clearance_number']) ?></strong><br><?= e($clearance['invoice_no']) ?></div></header><div class="meta"><div><strong>Customer</strong><?= e($clearance['customer_name'] ?? 'Walk-in') ?><br><?= e($clearance['customer_phone'] ?? '') ?></div><div><strong>Vehicle / Driver</strong><?= e($clearance['vehicle_plate']) ?><br><?= e($clearance['driver_name'] ?? '—') ?> <?= e($clearance['driver_phone'] ?? '') ?></div><div><strong>Date / Time</strong><?= e(date('d M Y H:i', strtotime($clearance['generated_at']))) ?></div><div><strong>Payment</strong><?= e($clearance['payment_status']) ?><br><?= e($clearance['payment_reference'] ?? 'No reference') ?></div></div><table class="items"><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['name'] . ' ' . $item['size']) ?></td><td><?= number_format($item['quantity']) ?></td><td><?= e(currency_symbol()) . money($item['unit_price']) ?></td><td><?= e(currency_symbol()) . money($item['quantity'] * $item['unit_price']) ?></td></tr><?php endforeach; ?></tbody></table><div class="total"><div><span>Grand total</span><strong><?= e(currency_symbol()) . money($clearance['total_amount']) ?></strong></div><div><span>Amount paid</span><strong><?= e(currency_symbol()) . money($clearance['paid_amount']) ?></strong></div><div><span>Balance</span><strong><?= e(currency_symbol()) . money($clearance['balance']) ?></strong></div></div><?php if($clearance['status']==='READY_FOR_GATE'): ?><div class="status">✓ PAID · LOADED · VALID CLEARANCE · VEHICLE MAY EXIT</div><?php elseif($clearance['status']==='EXITED'): ?><div class="status">✓ EXITED at <?= e(date('d M Y H:i', strtotime($clearance['exit_time']))) ?></div><?php elseif(in_array($clearance['status'],['REJECTED','CANCELLED'],true)): ?><div class="status" style="background:#fee2e2;color:#b91c1c;">⛔ <?= e($clearance['status']) ?> — VEHICLE MAY NOT EXIT<?= !empty($clearance['cancellation_reason']) ? '<br><span style="font-weight:normal;">Reason: ' . e($clearance['cancellation_reason']) . '</span>' : '' ?></div><?php else: ?><div class="status" style="background:#fff3cd;color:#92400e;">WAITING FOR LOADING CONFIRMATION</div><?php endif; ?><div class="qr"><img src="https://api.qrserver.com/v1/create-qr-code/?size=140x140&amp;data=<?= urlencode($verifyUrl) ?>" alt="Clearance QR code"><div><?= e($clearance['clearance_number']) ?></div></div><div class="sign"><div>Authorized by</div><div>Gate guard</div><div>Exit time / signature</div></div><p style="font-size:12px;text-align:center;margin-top:28px;">Valid only for the vehicle and products listed above.</p></main></body></html>